window.HARDTRP.receive("177926",[[177927,"2026-08-30T09:35:34",9,"Начало темы.\n\n@dunchev — Дм этой темы.",177926,null],[178885,"2026-08-30T14:55:49",17,"Здесь человек живёт между огнём и холодом.\n\nИллуг прибился недавно, его сторонятся но не изгоняют. На севере есть закон, никого нельзя оставлять в беде. Поэтому его юрта на окраине стойбища спокойно существует.\n\nЖивёт он с собаками, сам добывает себе пропитание и не создаёт проблем.\n\nСегодня он как обычно выдвинулся проверить силки и свой рыбный тайник.\n\nПозади осталось маленькое стойбище Иллуга — несколько тёмных крыш, дым над юртами и люди, которых он знает с детства. Впереди лежит тундра: белый снег, чёрный камень и далёкие сопки, над которыми медленно тянется вулканический дым.\n\nМоре осталось где-то за спиной. Его не видно, но ветер всё ещё пахнет солью.\n\nПолозья негромко режут снег.\n\nЕздовые собаки идут ровно. Они знают эту дорогу не хуже Иллуга. Сегодня ничего необычного быть не должно — проверить силки, добраться до старого запасника и повернуть домой до темноты.\n\nПередняя собака вдруг сбавляет ход.\nЗа ней вторая.\nУши поднимаются почти одновременно.\nНа снегу впереди пересекают старую дорогу человеческие следы.\n\nОдин человек.\nБез упряжки.\nБез саней.\n\nСледы уходят в сторону каменной гряды, туда, где зимой одинокому путнику делать почти нечего.\n\nСобаки молчат.\nТолько старшая тихо скулит, не сводя глаз с далёких камней.\n\nТы знаешь следов просто так здесь быть не должно",177926,null],[178888,"2026-08-30T14:56:38",17,"Следы",177926,null],[178968,"2026-08-30T15:08:46",9,"//Ладно, я не понимаю что происходит. Все, живы? Зачем мне проверять силки? Зачем возвращаться домой? Это когда было, как, я не понимаю ~",177926,null],[178971,"2026-08-30T15:09:08",17,"/ Там не твоя семья",177926,null],[178972,"2026-08-30T15:09:13",17,"/ Просто племя где ты временно",177926,null],[178973,"2026-08-30T15:09:20",17,"/ Ты пошел добыть себе и собакам еду",177926,null],[178975,"2026-08-30T15:09:46",17,"/ Дом твоя Юрта на отшибе, живешь ты с собаками",177926,null],[178976,"2026-08-30T15:09:54",17,"/ Остальное племя тебя сторонится",177926,null],[178977,"2026-08-30T15:09:58",17,"/ Но не изгоняют",177926,null],[178982,"2026-08-30T15:10:15",17,"/ Ну давай в ЛС подкорректируем как ты хочешь, чтоб было логичнее твоей задумке",177926,null],[178983,"2026-08-30T15:10:22",17,"/Мне не помешает это я поправлю",177926,null],[178989,"2026-08-30T15:10:50",9,"//А, добрые люди, я понял. Просто я не хотел повторять историю что уже в преле написал, а тут другое",177926,null],[178992,"2026-08-30T15:10:58",17,"/ Нет другое",177926,null],[178995,"2026-08-30T15:11:04",17,"/ На севере закон",177926,null],[178996,"2026-08-30T15:11:09",17,"/ Нельзя оставлять в беде никого",177926,null],[178999,"2026-08-30T15:11:43",9,"//Да, есть такое, они не откажут. Нус щас буду расчехляться. Мне чет показалось совсем другое, я не знал контекста)",177926,null],[179002,"2026-08-30T15:11:58",17,"/ Ну допишу сейчас",177926,null],[179073,"2026-08-30T15:21:02",17,"/ Ну ситуация думаю теперь понятна, ты просто поехал проверить свои силки",177926,null],[179104,"2026-08-30T15:26:44",9,"//Ладно, остался один вопрос, насколько это место далеко от стоянки, саньми я понял доехать успею, а вот человек я так понял воротиться не успеет?",177926,null],[179106,"2026-08-30T15:27:17",17,"/В целом да, на севере закон, если можешь помочь, помоги",177926,null],[179112,"2026-08-30T15:28:23",9,"//Ты мне расказываешь))), щас пытаюсь понять что куда",179106,null],[179114,"2026-08-30T15:28:45",9,"//Вродь пока всё, буду думать",177926,null],[179121,"2026-08-30T15:29:28",17,"Следы ведут чуть в сторону от твоего маршрута,.\n\nПонятно одно человек без упряжки на таком расстоянии от известных тебе стоянок либо потерялся в пурге либо ищет смерти тут",177926,null],[179288,"2026-08-30T15:53:55",9,"*Есть старая сказка которую расказывали детям.*\n\nБелая мышь запрягла в сани блох, близко была ночь. Продолжи\n\n*Будучи детьми те могли придумать множество того как закончилась эта история. Починили постромки, мышь починила сани или ей помогла птица на которой мышь долетела. Но у сказки была и вторая половина расказа:*\n\nПешком, пешком иди домой.\n\n*Не важно как, когда, детям расказывади сказки что учили их не сдаваться, просто делать.*\n\n*Иллуг встал с саней, взяв с собой копьё, он присел рядом с Апутсиак (снежинка), самой старой из собак.*\n\nИллуг — Беда у скал? — *Он проследил за её взглядом, туда ли шёл человек? А даже если и туда, это ничего не меняет. Он приобнял собаку немного потрепав ей холку и уткнувшись лицом в густую шерсть, показать что он рядом.* — Апу, нам надо идти. — *Зная что духи где то там, птицы, животные, ворон которого не заметить глазами, где то там, рядом, он бросил взгляд в пустое небо.* — Знаю, беда обойдёт нас стороной. Мы не сделали ничего что разозлит хозяина этих мест.\n\n*Успокоив (или попытавшись успокоить) собак, пусть сани идут по следам. Может кому то нужна помощь там.*",177926,null],[179333,"2026-08-30T16:03:09",17,"Следы уводят между чёрных камней.\nЗдесь ветер слабее. Собаки идут медленнее, часто втягивая носами морозный воздух.\n\nНа снегу появляется глубокий отпечаток колена.\nПотом ещё один сбившийся шаг.\nЗа поворотом между базальтовыми глыбами сидит человек.\n\nСтарик. Худой, жилистый, закутанный в старые меха. Седые волосы выбились наружу и покрылись инеем. На одежде покачиваются костяные подвески и несколько потёртых вороньих перьев.\n\nНи саней.\nНи собак.\nДаже нормальной поклажи при нём нет.\nСтарик поднимает голову на звон упряжи и долго смотрит на Иллуга.\nПотом переводит взгляд на собак.\n\n— Хорошие.\n\nОн снова смотрит на Иллуга.\n\n— Хозяин тоже ничего. \n\nСтарик пытается подняться, опираясь ладонью о камень.\nНоги подводят его, и он с досадой снова садится в снег.\n\n— Только не смей смеяться. Старость не радость парень.",177926,null],[179410,"2026-08-30T16:15:23",9,"— Аата (деда), куда вас вели ноги. — *Иллуг подходит и помогает старику подняться. Он помогает встать, улыбается на слова, но это не смех и не насмешка.* — Весь мир отразился в ваших глазах, мудрость стоит уважения.\n\n*Иллуг искренний, немного путает слова местами, говорит не так как обычные люди. Он знает старость, он её видел у других, он знает что и сам будет когда-то там.*",179333,null],[179421,"2026-08-30T16:18:19",17,"Тот отвечает коротким кивком.\n\n— Меня зовут. Налгын.\n\nСтарик произносит имя так, словно этого достаточно.\n\n— Живу за северной сопкой.\n\nВ уголках его глаз появляется сухая усмешка.\n\n— Шаманю понемногу. Лечу тех, кто слишком упрям, чтобы умереть и борется.\n\nОн медленно растирает пальцы.\n\n— Ходил к охотничьей хижине. Человек там свалился с жаром. Назад возвращался — пурга накрыла.\n\nНалгын смотрит куда-то поверх плеча Иллуга, будто пытается восстановить дорогу в памяти.\n\n— Здесь лёг. Между камней. Думал, ветер пережду.\n\nНебольшая пауза.\n\n— Проснулся — тихо уже.\n\nОн хмурится.\n\n— Вчера, кажется.\n\nСтарик поднимает глаза на Иллуга.\n\n— А ты куда путь держишь?",177926,null],[179538,"2026-08-30T17:18:54",9,"//Я знаю как далеко северная сопка? Или эт чёт неизвестное",177926,null],[179543,"2026-08-30T17:21:15",17,"Это по направлению туда же куда тебе надо. Чуть ближе чем твой запасник рыбный",177926,null],[179608,"2026-08-30T17:34:56",9,"— Снег сани легко несёт, садитесь Аата Налгын, пойдём к вам домой, мой путь лежит не далеко. — *Парень даже не думал, он говорил, место рядом, не далеко.* — Я Друг (Иллуг).",179421,null],[179685,"2026-08-30T18:00:13",17,"Он криво улыбается.\n\n— Значит проводишь меня? Замечательно Иллуг.\n\nСтарик поднимается, отряхивает снег с мехов и, будто вопрос уже решён, идёт рядом с упряжкой.",177926,null],[179689,"2026-08-30T18:01:20",17,"Проходит совсем немного времени.\n\nВпереди снег кажется ровным и нетронутым.\n\nПервая в упряжке собака делает шаг.\nБелая корка под ней исчезает.\n\nРаздаётся треск.\n\nСобака с визгом проваливается грудью в чёрную воду, упряжь натягивается, остальных резко дёргает назад. Сани начинают боком скользить к пролому.\n\nНалгын мгновенно оживает.\n\n— Стой! Не тяни! Задушишь!\n\nОн уже срывает с себя длинный кожаный ремень.\n\n— Успокой остальных! Я подберусь сбоку!\n\nСобака судорожно цепляется лапами за крошащийся лёд.\n\nВода вокруг неё становится всё шире.",177926,null],[179700,"2026-08-30T18:03:38",9,"//Черт, вот хотел же крюк копьё из кости длинное, как у настоящих Инуитов, щас бы с берега зацепить за упряжь на спине да вытащить.",177926,null],[179716,"2026-08-30T18:12:49",9,"*Иллуг достаёт копьё и бёт им в снег между вязами чтобы сани не ушли дальше вместе со всеми, после отцепляет постромки, упряжь с собаками. Анука (ветер) шел первым, самый быстрый, уверенный но и не осторожный.*\n\n— Тихо, тихо. — *Он обнял самого паникующего из собак, Медвежонка, девочки были более спокойны а большой пёс, самый молодой и беспокойный рвался дальше от воды. Налгын выглядел так словно знал что делает, Иллуг решил ему довериться.*",177926,null],[179906,"2026-08-30T18:54:00",17,"/ Уход за животными кинь с преимуществом",177926,null],[179923,"2026-08-30T18:56:02",9,"/roll +d20+1 ну, бонусы у меня везде не ахти)",177926,null],[179925,"2026-08-30T18:56:09",17,"Налгын сам ложится на живот и ползёт к пролому, распределяя вес. Продевает длинный ремень под грудью Анука и командует Иллугу\n\n— Не вверх тяни. На себя, по льду. Медленно.",177926,null],[179927,"2026-08-30T18:56:17",17,"/ Атлетика на сколько копье надежно",177926,null],[179931,"2026-08-30T18:56:37",17,"Собаки паникуют и расшатывают копьё",177926,null],[179932,"2026-08-30T18:56:41",9,"/roll 1d20+1 атлетика",177926,null],[179939,"2026-08-30T18:57:23",9,"//Я упряжку собак отцепил от саней, но лан",177926,null],[179941,"2026-08-30T18:58:36",17,"/ Их тогда утянет упряжка. Сани держат своим весом",177926,null],[179943,"2026-08-30T18:58:40",17,"/ Отцепил?",177926,null],[179946,"2026-08-30T18:59:04",9,"//Выходит да, я не люблю исправлять ошибки",177926,null],[179948,"2026-08-30T19:00:04",9,"//. Вот, мне показалось что сани уйдут вместе с собаками и сделал",179716,null],[179974,"2026-08-30T19:10:29",17,"Сани задерживаются \n\nСобаки пытаются вытянуть Анука но разрозненно, сказывается паника и страх\n\n/ Можешь ещё раз попробовать испокоить их или тащить силой",177926,null],[179975,"2026-08-30T19:10:57",17,"Налгын обернув ремнем Анука тянет",177926,null],[179976,"2026-08-30T19:11:03",17,"/ Преимущество везде",177926,null],[180061,"2026-08-30T19:28:50",9,"/roll +d20+1 уход за животными пусть",177926,null],[180068,"2026-08-30T19:29:25",17,"/ Тебе удалось успокоить их и направить. Опиши как вы спасёте из воды Анука",177926,null],[180071,"2026-08-30T19:29:39",17,"/r +1 Атлетика дедушки",177926,null],[180098,"2026-08-30T19:34:51",9,"*Иллуг понимает что Медвежонка успокаивать бесполезно, он направляет снежинку и подругу чтобы они тащили в одну сторону. Когда ему это удается он помогает дедушке выбраться.*\n\n— Дердитесь Аата! — *Он обвязывает себя верёвкой, веревку к саням и ползёт помогать Налгыну, уже подтягивая на берег его.*\n\n//Дед ребку, репка внучку, внучка жучку как там",177926,null],[180120,"2026-08-30T19:43:13",17,"Анука выбирается на снег и несколько секунд просто лежит, тяжело дыша.\n\nПотом пытается подняться.\n\nЛапы дрожат.\n\nНалгын проводит рукой по его мокрому боку.\n\n— Не пойдёт сейчас.\n\nОн указывает на чёрные скалы неподалёку.\n\n— Там есть пещера. Ветер не достаёт. Огонь разведём, шерсть просушим.\n\nСтарик смотрит на Иллуга.\n\n— Быстро соображаешь. Молодая кровь. \n\nНебольшая пауза.\n\n— Видно, что они тебе не просто собаки.",177926,null],[180228,"2026-08-30T20:11:11",9,"*Иллуг переворачивает сани, ложит Ануку на сидение, укутывает чем есть при себе, чем может, снимает свой верхний наряд.*\n\n— Анука (ветер), Ила (друг - \"подруга\"), Нанухак (медвежонок) и Апутсиак (снежинка, та что самая старшая), все — семья. — *Врягает троих не намокших, но сам не садится, ведёт упряжь держась за свободный поводок. Он был немного грустным, но улыбался когда говорил о них.* — Большое спасибо Аата (деда) Налгын. Ваши руки сразили беду, с ней я не справился один.",180120,null],[180237,"2026-08-30T20:13:25",17,"Налгын некоторое время молча идёт рядом.\n\nНа слове \"Аата\" он косится на Иллуга, будто хотел что-то съязвить, но передумывает.\n\n— Руки руками. Твои собаки не запаниковали, ты не запаниковал, вот что важно.\n\nОн поправляет мех на укутанном Ануке.\n\n— В тундре человек, который думает, что справляется один, обычно недолго остаётся человеком. Потом его называют покойником.\n\nСтарик хмыкает.\n\n— Так что благодарность принимаю. Но долг мне не выдумывай.\n\nНалгын смотрит на собак, потом на чуть грустную улыбку Иллуга.\n\n— Хорошая семья.\n\nИ больше ни о чём не спрашивает.",180228,null],[180326,"2026-08-30T20:36:13",9,"— Вы хошоший человек. — *Иллуг всё так же улыбался, словно был немного дурачком. Правда его руки делали быстрее чем от думал, суровая жизнь Кыиланги закалила его. Иллуг вспомнил о родных, тех которых уже нет, просто дал совет, может он пригодится старику, или тот поведует кому.* — Человек со звериными глазами как у снежной рыси — злой человек. Ваши руки гонят беду, великий шаман.",180237,null],[180420,"2026-08-30T20:57:51",17,"До скал добрались медленно.\n\nТрое собак тянули сани, Иллуг шёл рядом, а Налгын держался возле укутанного Ануки и время от времени проверял его лапы.\n\nМежду чёрных базальтовых выступов нашлась узкая пещера — неглубокая, но сухая и почти полностью закрытая от ветра.\n\nСани поставили у входа заслоном.\n\nУстроили собак внутри, на сухом камне, подальше от сквозняка. Налгын вытащил из щелей старую сухую траву и ломкие ветви карликового кустарника.\n\nЧерез несколько минут в темноте затрещал маленький костёр.\n\nСначала пламя было слабым, синим у основания, потом разгорелось и окрасило стены пещеры тёплым светом.\n\nАнуку уложили ближе всех к огню.\n\nПар начал медленно подниматься от его шерсти.\n\nНалгын сел напротив, протянул ладони к пламени и посмотрел на Иллуга поверх костра.\n\n— Вот теперь можно немного пожить.",177926,null],[180465,"2026-08-30T21:32:11",9,"*Иллуг снял одёжку так чтобы она грела спину от стены, оставшись в простой одежде, грелся у костра, сох. Он достал кусок обсушенного до твердого состояния моржового мяса в жиру, срезал тонкую его полоску, неспеша жевать, гладил Аннуку лежащего у костра. Без соли и специй он делился с собаками своей едой, поделился бы и Налгыном если тот захочет, вообще без вопросов.*\n\n— Часто здесь уходит лед из под ног? — *Спросил Иллуг, он был не внимательным, плохо читал местность. Может стояло впереди упряжи поставить не храброго Аннуку, старшую Аппутсиак, та могла и не йти в лёд. Он взглянул в сторону улицы, что говорит время, успеет ли он вернутся или прийдется день провести в пути. Он не так много взял с собой поклажи.*\n\n*Без дорожной одежды зимы, да плотных перчаток, на ладонях, кистях и предплечьях парня было видно татуировки, десятки летящих птиц? Нет, они грубые, вызженные углями, жиром, словно ритуал или тайна (та способка что стихийный дар от гения что даст летать, типа руки будут обрастать перьями и становится крыльями, но нарративно это типа особого ритуала).*",177926,null],[180472,"2026-08-30T21:35:25",17,"Налгын взял полоску мяса и кивнул в знак благодарности\n\n— Лёд здесь не уходит никогда. Это анамалия мальчик. Духи поогневались не иначе. Я не пойму только за что. \n\nОн достал губной варган и сыграл на нем мелодию \n\n— Пока мы тут, я могу поведать тебе несколько мудрых баек, что услышал от давно мертвых учителей. О мире духов и о тех, кого зовут шаманами парень.",180465,null],[180515,"2026-08-30T21:49:49",9,"— Я знаю, шаманом называют тех, кто видит, кто слышит. — *Иллуг на деле знал лишь малые основы.* — Все люди немного шаманы, но знаю лишь сказки и то что расказали птицы. — *Парень улыбнулся.* — Раскажите сказку Аата Налгын, я буду внимательно слушать.",177926,null],[180517,"2026-08-30T21:52:11",17,"Когда я был моложе тебя, мой учитель говорил: духа нельзя звать только потому, что тебе любопытно.\n\nЯ тогда спросил его \"Почему? Разве шаман не должен знать духов?\"\n\nОн взял палку и постучал по льду.\n\n— Ты ведь знаешь, что под нами вода. Но не пробиваешь лёд каждый раз, когда хочешь убедиться.\n\nНекоторые двери полезно знать.\nОткрывать их необязательно.",177926,null],[180519,"2026-08-30T21:53:24",17,"Был мой учитель. Очень злой старик. Говорил мало, бил больно.\n\nОднажды он заставил меня три дня смотреть за вороном.\nЯ думал, он хочет научить меня понимать птиц.\nНа третий день спросил\n\n— Ну? Что сказал тебе ворон?\n\nЯ ответил, что ничего.\nСтарик рассмеялся.\n\n— Вот и хорошо. Значит, начинаешь учиться. Молодые шаманы слишком хотят, чтобы всё вокруг с ними разговаривало.\n\nОн сказал - прежде чем услышать духов, надо научиться отличать их голос от собственного желания услышать ответ.\n\nИначе всю жизнь будешь разговаривать сам с собой и называть это мудростью.\n\n— Тогда тебя прозовут безумцем, а не шаманом.",177926,null],[180529,"2026-08-30T21:57:15",17,"Еще этот старик говорил мне, что у человека три смерти.\n\nПервая — когда тело перестаёт греться.\n\nВторая — когда последний человек забывает твоё лицо.\n\nА третья — когда исчезает последняя вещь, которую ты изменил в мире.\n\nПотом он показывал на старую тропу между сопками и сказал.\n\n— Видишь? Её протоптал человек, которого уже никто не помнит. Но люди всё ещё ходят там и не проваливаются в талину.\n\nОн говорил, что некоторые мёртвые дольше живых помогают людям.\n\n— Поэтому не спеши жалеть умерших. Иногда им уже хорошо. А вот живым почти всегда есть от чего страдать.",177926,null],[180590,"2026-08-30T22:25:25",9,"*Иллуг внимательно слушал, особенно последнюю часть, он вспомнил кое что, то что говорила его бабушка. Она была странной женщиной и умерла когда он был совсем юн, плохо её помнил.*\n\n— Аана (бабушка) говорила мне что что когда о человека забудут он уйдёт дальше. — *Тихо пробомотал он под нос. Его рука зарылась в мех Ануки (ветра) что понемногу обсыхал, он задумался, и сказал:*\n\n— Хочу слушать что они говорят, но со мной говорят лишь птицы. Сказки том что там есть места, тёплые, где ледяная ночь не забирает солнце (говорил о долгой северной ночи, самой холодной части зимы когда солнца не видно). Хотелось улететь вместе с ними, они говорили что у меня никогда не получится, потому что нет перьев, голая кожа на крыльях. — *Он имел ввиду руки, наглядно оттянув немного кожи на запятстье.* — Неоперившийся птенец.",177926,null],[180694,"2026-08-30T23:18:39",17,"Налгын долго смотрел на руку Иллуга.\n\nНе смеялся.\n\n— Птицы жестокие учителя. Они всегда начинают с того, чего у тебя нет.\n\nСтарик подбросил в огонь сухую ветку.\n\n— Моему учителю тоже хотелось летать. Он говорил, что шаман всю молодость пытается стать птицей, зверем или духом. А потом стареет и понимает — труднее всего было остаться человеком.\n\nНалгын помолчал.\n\n— Если они говорят тебе о тёплых землях, слушай. Птицы знают дорогу лучше нас. Но не всякий их рассказ это приглашение.\n\nОн указал костлявым пальцем на грудь Иллуга.\n\n— Ты ведь тоскуешь не по тёплой земле. Ты тоскуешь по месту, где нет боли.\n\nТреснуло полено.\n\n— Такие места тоже существуют.\n\nСтарик криво усмехнулся.\n\n— Только живых там обычно не ждут.\n\nЕго взгляд снова скользнул к нарисованным птицам на руках Иллуга.\n\n— А перья...\n\n— Не спеши отращивать. У всех, кто умеют летать между мирами, есть одна беда.\n\nНалгын протянул ладони к огню.\n\n— Они однажды забываеют, где их родная земля.",177926,null],[180734,"2026-08-30T23:41:17",17,"Налгын долго молчал, глядя, как огонь лижет почерневший камень.\n\n— Хочешь сказку про Ворона?\n\nОн не ждал ответа.\n\n— Когда мир был ещё молод, зима однажды решила не уходить.\n\nСолнце пряталось за краем неба, море стало твёрдым до самого дна, а люди жгли последние доски своих домов, чтобы не замёрзнуть.\n\nТогда Ворон полетел искать тепло.\n\nОн летел три дня и три ночи, пока не увидел посреди белой равнины старуху.\nОна сидела возле проруби и держала в руках маленькое красное солнце.\nНе настоящее. Совсем крошечное. Такое можно спрятать под языком.\n\nВорон спросил\n\n\"Отдай его людям.\"\n\nСтаруха сказала\n\n— Нет.\n— Они умрут.\n— Все умирают.\n\nТогда Ворон предложил ей рыбу.\nОна отказалась.\nПредложил золотые камни с морского дна.\nОна отказалась.\nПредложил своё имя.\nСтаруха впервые посмотрела на него.\n\n— Имя мне не нужно. Отдай мне одну свою память. Самую дорогую.\n\nВорон долго думал.\nА потом вспомнил первое гнездо. Тёплое брюхо матери. Запах мокрых перьев. Голос, который когда-то называл его птенцом.\n\nОн отдал эту память.\n\nСтаруха положила маленькое солнце ему в клюв.\nВорон принёс его людям.\nОни развели от него первый зимний огонь и пережили холод.\nВсе благодарили Ворона.\nВсе называли его спасителем.\n\nА он смотрел на них и не понимал, почему ему так тяжело.\nПотому что уже не помнил, что потерял.\n\nНалгын пошевелил угли палкой.\n\n— Мой учитель говорил - духи любят именно такие сделки.\n\n— Они редко забирают то, без чего ты не можешь жить.\n\nСтарик поднял глаза на Иллуга.\n\n— Они забирают то, без чего ты однажды перестанешь понимать, зачем живёшь.\n\nОн чуть улыбнулся.\n\n— Поэтому, если Ворон когда-нибудь предложит тебе тепло посреди самой долгой ночи, сначала спроси цену.\n\n— А потом уж принимай решение.",177926,null],[180790,"2026-08-31T00:06:02",9,"*Иллуг тоже молчал некоторое время. Извиняющейся улыбнулся.*\n\n— Сказка очень далека, но так знакома. Из далёкой Кыиланги сказка о вороне. Вороне укравшем песню героя. — *Иллуг отрезал ещё полоску мяса, ушел уже добрый клапоть, Анука перестал трусится от холода, когда как у старых костров, протянул Иллуг песню что хранили уста его племени.*\n\nВзойдёт палящее солнце Кыиланги.\n\nИдёт шаман неся в руках ворона укравшего песню героя.\n\nЗамурован в перьях, в полых костях да остром клюве, порыв души искренний, великий.\n\nДа за кругом не видно чужого простора.\n\nСказанное не имелось в виду, слова навлекли беду.\n\nПтица льёт правду в уши человеческим голосом.\n\n\"Сердце окаменей. И больше не смей, и больше не смей...\"\n\n*После неё Иллуг затих, погрущившись в думы, прежде чем откинуть их, и снова улыбнуться.*\n\n— Прости Аата Налгын. Я обещал ворону то чего у меня пока нет, свою песню героя. — *Он вспомнил что говорила бабушка, о том как уходили люди о которых забыли, и о том что умирают в третий раз когда от человека ничего не остаются.*\n\n— Когда умру, ворон украдёт мою песню героя, если найду. — *Почему-то, Иллуг не знал, хочет ли он этой судьбы.* — Если ворон будет петь мою песню героя, обо мне не забудут, не смогу уйти. — *Он поднял глаза ища совета у старшего.* — Стоит ли искать свою песню. Стоит ли просто жить и уйти когда ничего не останется. — *Он вздохнул и смущенну почесал затылок сощурив глаза.* — Я не знаю.",180734,null],[181053,"2026-08-31T01:52:33",17,"Огонь успел прогореть почти до углей.\nАнука наконец поднялся сам, встряхнулся и недовольно фыркнул, когда Иллуг проверил его лапы.\nНалгын только хмыкнул.\n\n— Жить будет. А характер, вижу, вода не смыла.\n\nОни вышли снова.\nДорога потянулась между белых низин и чёрных камней. Солнце уже клонилось ниже, тени от сопок становились длиннее.\nНекоторое время слышались только полозья и дыхание собак.\n\nПотом главная резко остановилась.\nНос поднялся.\nЗа ней насторожились остальные.\nНа белом снегу впереди темнело маленькое пятно.\n\nКрасное.\n\nЧуть дальше — ещё одно.\nИ ещё.\nНалгын присел возле первого, коснулся его пальцами.\n\nУлыбка исчезла с его лица.\n\n— Человеческая.\n\nОн посмотрел вдоль следа.\n\n— И крови слишком много.",177926,null],[181071,"2026-08-31T08:09:20",9,"*Иллуг не боялся крови, но боялся беды. Если живых никого нет, то и нет смысла рисковать.*\n\n— Аата (деда) Налгын, могу  попросить помощи. — *Предложил Иллуг.* — Ворон редко слушает, редко видится глазами, но когда большая беда — помогает.\n\n*Ворон всегда был где-то там, может в небе, может на скалах. А может сидел на санях. Но дух не давал себя увидеть если не хотел показаться сам.*\n\n//Да, как фамильяр он механически ток, я не хочу его юзать командами, так что сам решишь ответит ли он вообще на просьбы. Эт дух скорее, что хорошо ложится на то что бес механически становится невидимым)))",177926,null],[181073,"2026-08-31T08:11:06",9,"//Щас максимум на мнгновение взглянуть его глазами, что там впереди, если сдобрится на помощь когда попрошу",177926,null],[181074,"2026-08-31T08:11:27",17,"/Да можешь использовать так.",177926,null],[181075,"2026-08-31T08:11:54",9,"//Щас что Налгын скажет, так и глянем или сами",177926,null],[181076,"2026-08-31T08:19:10",17,"Ворон смотрит на тебя тёмными бусинами глаз. Он понимает твоё намерение на полуслове. Ты никак не разочаровывал его, поэтому он не станет противиться. ВОрон взлетает.\n\n— Похоже ты тоже долго следил за птицами юный Иллуг. Если там живой человек, наша обязанность проверить и помочь. Таков закон севера.\n\nФамильяр летит по кровавому следу, передаёт тебе увиденное, ты видишь вспышки образов в сознаннии и под конец ненадолго смотришь его глазами\n\nКровь ведёт вниз, в белую ложбину.\nСначала редкими каплями.\nПотом целыми тёмными пятнами.\nНа снегу появляется отпечаток ладони. Чуть дальше — глубокая борозда от колена.\nРядом с человеческим отпечатком в снег вдавлена огромная лапа.\nЕщё несколько десятков шагов.\n\nЗа чёрным каменным выступом лежит человек.\n\nМолодой мужчина в охотничьей одежде, бок весь в крови. Одна рука прижата к груди, дыхание редкое и хриплое.",177926,null],[181079,"2026-08-31T08:27:20",9,"— Помоги, ворон укравший песню героя. Укажи что впереди. — *Иллуг закрыл глаза сосредоточившись на ощущениях.*\n\n*Несколько обрывков видений показали сцены, самое важное, лишь мгновения.*\n\n— Аата Налгын, там человек, ещё живой, охотник. Большой зверь ранил, но дыхание не покинуло его, зима не забрала. — *Он не спрашивал надо ли идти. Руки отцепляли упряжь собачью. Даже если те останутся тут, без саней смогут уйти коли он не вернётся. Иллуг шёл вперёд, Иллуг идёт вперед, твердыми ногами, полными шагами.*",177926,null],[181080,"2026-08-31T08:30:23",17,"— Надо вытаскивать. Тут охотничья сторожка в той же стороне есть. Я там как то раз бывал, помогал раненому. Но... Большой зверь говоришь. Нужно быть очень острожными.\n\nНалгын встал\n\n— Успокой собак, попробуй сделать, чтоб они не лаяли и шли тихо. Без саней мы его всё равно не вытащим, а так хоть шанс есть. Иллуг.",177926,null],[181081,"2026-08-31T08:30:43",17,"/Уход за животными чтобы успокоить собак чующих кровь.\n\nСкрытность.",177926,null],[181082,"2026-08-31T08:35:41",9,"*Иллуг знал что самые беспокойные это Анука (ветер), и особенно молодой, крупный Нанухак (медвежонок), девчёнки были спокойнее, достаточно было успокоить медвежонка и следить за ветром. Иллуг повел медвежонка, идя рядом с ним, чтобы тот меньше невничал. Раз Налгын советовал, то будь везти раненого на санях.* \n\n— Тише, тише. — *Иллуг тихо тихо говорил, чтобы собаки слышали его голос, не так пугались.*",177926,null],[181083,"2026-08-31T08:35:54",9,"/roll 1d20+1 уход за животными",177926,null],[181085,"2026-08-31T08:36:34",17,"— Мы можем потратить немного из твоих запасов еды. Должно помочь",177926,null],[181086,"2026-08-31T08:36:41",9,"//Ну Нанухак паникёр, увидит зверя или чё случится всё",177926,null],[181087,"2026-08-31T08:37:55",9,"*Кивнул и достал угощение, сахарную кость в жиру. Медвежонок никогда от неё не отказывался, может станет поспокойнее.*",181085,null],[181088,"2026-08-31T08:38:04",9,"//Еще раз?",177926,null],[181089,"2026-08-31T08:38:05",17,"/ СЛ 10 по Уходу за животными. Перебрось за еду",177926,null],[181090,"2026-08-31T08:38:13",17,"/ Если пройдешь на скрытность будет преимущество",177926,null],[181091,"2026-08-31T08:38:23",9,"/roll 1d20+1 уход",177926,null],[181093,"2026-08-31T08:39:13",9,"*Сделав все что может, Иллуг все де старается вести свои сани тихо.*",177926,null],[181094,"2026-08-31T08:39:17",17,"— Молодые, они должны больше доверять тебе Иллуг",177926,null],[181095,"2026-08-31T08:39:43",9,"/roll 1d20+2 скрыт выходит без преима",177926,null],[181097,"2026-08-31T08:41:35",9,"— Простите Аата Налгын. Я с ними в пути не так давно. Они были друзьями моих родных.",181094,null],[181098,"2026-08-31T08:42:20",9,"— Может мы потащим сани сами. Тут немного, а они подождут нас здесь. — *Иллуг был серьезен, он точно знал что Нанухак (медвежонок) спаникует, слишком молодой и боязливый.*",177926,null],[181099,"2026-08-31T08:46:08",17,"Старик хмурится, вы идёте шумно\n\n— До стойбища до темна не дотянем. Там\n\nУказывает по направлению крови на северо восток \n\n— Охотничья Сторожка, Иллуг. Нам нужны собаки, чтобы вытащить охотника. А если придётся бежать.... Без них у нас шансов нет\n\nСнег предательски хрустит. Но самое это запах крови в воздухе. Человеческой перемешаной с животной\n\nДойдя до следов зверя Налгым хмурится еще больше и шепотом говорит тебе\n\n— Медведь.\n\nЧерез некоторое время Налгын вдруг поднимает руку.\n\n— Стой.\n\nВпереди над белой ложбиной кружат вороны.\nОдна птица садится на чёрный камень.\nПод ним темнеет большая туша.\nНалгын тихо произносит\n\n— Вот откуда он пришёл.\n\nИз-за туши медленно поднимается огромная бурая голова.",177926,null],[181100,"2026-08-31T08:46:09",9,"*Нанухак похоже был так насторожен что не повелся на любимую сазарную кость.*",181092,null],[181102,"2026-08-31T08:47:01",17,"Он е нападает сразу, он защищает добычу. Пока что. Но собаки его явно нервируют",177926,null],[181103,"2026-08-31T08:54:42",9,"*Иллуг буквально обнял морду Нанухака (медвежонка) и прикрыл глаза Ануке (ветру) чтобы не дай кто-то из них не залаял на нанухака (медведя) побольше. Апутсиак (снежинка) или Ила (подруга) не залают первыми, обычно не лаяли первыми *\n\n— Идём, пешком идём. — *Шепчет он и задкует ведя собак. Осторожно и сам не поворачивается спиной. Да не смотрит в глаза медведя, только на его лапы, чтобы не нервировать зверя. Одинокий зверь не нападет на толпу просто так, так говорили охотники Кыиланги.*\n\n//Надеюсь нам не прямо к медведю, тогда прийдется пугать михалыча сворой лающих собак, хз",177926,null],[181107,"2026-08-31T10:06:33",17,"Медведь поднимает голову.\nОн заметил.\nНесколько мгновений огромный зверь просто смотрит.\nПотом медленно поднимается над тушей.\nПередние лапы уходят глубоко в снег.\nРёв прокатывается между камнями.\n\nСобаки напрягаются под руками Иллуга. Нанухак отвечает низким рычанием. Анука пытается вывернуть голову из-под ладони.\n\nМедведь делает шаг.\nПотом второй.\n\nНалгын очень тихо говорит позади\n\n— Не беги.\n\nЕго рука уже сжимает связку костяных подвесок на груди.\n\n— Если хочешь напугать его — пугай сейчас. Всеми голосами сразу. Собаки должны звучать в унисон, Иллуг.\n\n— А если не послушает...\n\nСтарик поднимает взгляд на снег, который ветер гонит вдоль земли.\n\n— Тогда попрошу ветер.",177926,null],[181302,"2026-08-31T12:50:42",17,"/Твоё действие",177926,null],[181306,"2026-08-31T12:52:03",9,"//Я думвю, оно очевидно, но мне сложно собрвться с мыслями по этому поводу)",177926,null],[182352,"2026-08-31T17:19:37",9,"*Иллуг открывает глаза Ануке, перестаёт держать пасть Нанухаку.*\n\n— Грррааааррррр!!! — *Он пытается сымитировать рёв, лай, машет широко копьём и бьёт им по земле. Рядом кажется много камней, он идёт по ним, чтобы казаться выше.*\n\n— Уйди! Нам не нужна твоя добыча великий Нанухак! Мы заберём своего брата людского, оставим то что принадлежит тебе по праву!",177926,null],[182358,"2026-08-31T17:20:43",17,"/Уход за животными или запугивание",177926,null],[182371,"2026-08-31T17:24:48",9,"/roll 1d20+1 а тут как бы без разницы пусть будет уход, стараюсь дать понять что мы не мешаем, ритуала нет времени",177926,null],[182373,"2026-08-31T17:24:55",9,"//Ааааа",177926,null],[182377,"2026-08-31T17:25:21",9,"//Похоже ритуал разговора с животными сам кастонулся и медведь всё понял 😂👍",177926,null],[182471,"2026-08-31T17:59:03",9,"//Иллуг и Медведь 😂",182469,null],[183696,"2026-08-31T23:29:58",17,"Рёв Иллуга подхватывают собаки.\nСначала Нанухак.\nПотом Анука.\nЧерез мгновение вся упряжка превращается в единый гул рычания и лая.\n\nКопьё ударяет о камень.\n\nМедведь замирает.\nЕщё шаг...\n\nНо уже назад.\n\nОн поднимается над тушей, огромный, тяжёлый, страшный, и отвечает последним рёвом.\n\nПредупреждением.\n\nПотом опускается на четыре лапы и остаётся возле своей добычи.\n\nДорога свободна.\n\nНалгын медленно разжимает пальцы на костяных подвесках.\nНесколько секунд смотрит на Иллуга.\n\n— Хорошо.\n\nСтарик усмехается.\n\n— Очень хорошо.\n— Ты не заставил зверя бояться тебя\n\nОн кивает в сторону медведя.\n\n— Ты объяснил ему, чего хочешь\n\n— Многие шаманы и к старости этому не научились.",177926,null],[183726,"2026-09-01T08:17:39",17,"— Пойдём, Иллуг. Пока он не передумал.",177926,null],[183727,"2026-09-01T08:18:40",17,"Вы добираетесь по следу из крови до раненого охотника\n\nНалгын опускается рядом.\n\nНесколько секунд смотрит на его лицо.\n\n— Я его знаю. Он из моего стойбища.\n\nПотом коротко бросает Иллугу\n\n— Помоги поднять его на сани парень.",177926,null],[183729,"2026-09-01T08:20:14",9,"//Щас соберусь и буду играть наверное, ла и не ток играть",177926,null],[183731,"2026-09-01T08:21:04",17,"Раненого осторожно укладывают на сани.\n\nОн почти ничего не весит, но вместе с ним упряжка сразу идёт тяжелее.\n\nНалгын затягивает на его боку временную повязку и поднимается. \nОн показывает на северо-восток.\n\n— Туда. К охотничьей сторожке. Крыша цела, печь должна быть. Если доберёмся туда — у него появится шанс.",177926,null],[183925,"2026-09-01T13:09:23",9,"— Становитесь на сани Аата Налгын. Упряжка плохо потащит двоих, я побегу рядом. — *Иллуг взял лишок поклажи на себя, он то ничего, немного пробежится рядом направляя собак. Деда может за ним не поспевать, за  лежащим последит.*",177926,null],[184002,"2026-09-01T13:36:29",17,"Старик кивает и спорить явно не будет, его старые кости ноют уже давно. К этому невозможно привыкнуть.",177926,null],[184004,"2026-09-01T13:37:11",17,"Лес принимает их ближе к сумеркам.\nСопки постепенно исчезают за чёрными стволами. Дорога становится уже, полозья иногда цепляются за скрытые под снегом корни.\nСобаки устали.\n\nНа санях раненый начинает метаться.\nНалгын подходит ближе, поправляет на нём мех и кладёт ладонь на лоб.\n\n— Жар усилился.\n\nОхотник вдруг открывает мутные глаза.\nНесколько секунд смотрит куда-то мимо Иллуга.\nА потом тихо произносит\n\n— Налгын...\n\nСтарик замирает.\n\n— Тише. Силы береги.\n\nРаненый пытается поднять руку.\n\n— Ты... пришёл...\n\nНалгын крепче укрывает его мехом.\n\n— Потом поговорим. Сначала не умри.\n\nОн выпрямляется и смотрит вперёд, туда, где лес уже почти стал сплошной темнотой.\n\n— Сторожка близко уже",177926,null],[184086,"2026-09-01T13:58:37",9,"*Иллуг шел рядом с повозкой, уже подуставший, ноги едва поспевали вместе с собаками. Ближе к сторожке он сбросил часть ноши с себя обратно на сани, чтобы не отствать, собаки без него не пойдут, чужого человека не послушают.*\n\n— Белая мышь... запрягла в упряжку блох... Порвались постромки... пешком... пешком домой иди... — *Парень пока бежал слегка облоколся на сани, мгновение перевести дух. Заметив что охотник в себе, пока отдышался вспомнил вслух детсткой сказки слова, что учила никогда не сдаваться. Может для человека, а может и для себя, слегка выровняв дыхания он поплелся дальше вести собак мимо корней и преград.*",177926,null],[184115,"2026-09-01T14:07:14",17,"Сторожку вы находите уже в темноте.\nМаленький сруб стоит между чёрных деревьев, почти по крышу занесённый снегом.\nВнутри пахнет старым дымом, сухой древесиной и звериными шкурами.\n\nОгонь в печи разгорается быстро.\nРаненого укладывают на нары. Собаки устраиваются ближе к теплу.\nНа несколько часов мир снова становится маленьким.\n\nОгонь. Дыхание. Потрескивание дерева.\n\nНалгын делает раненому перевязку и припарки с травами\n\n— Смотри Иллуг, так правильно спасать жизнь. Но твоя помощь лишь половина пути, вторую половину больной должен пройти сам.",177926,null],[184127,"2026-09-01T14:15:53",9,"*Иллуг полумал и вышел на улицу, он притащил шкуру оленя что была ранее постелена на дне саней. Обычная шкура, но с отбратной стороны, слегка потертые ритуалы, рисунки отдельных фигур делающих определенные вещи (очищение воды и пищи есть).*\n\n— Аата Налгын, может это поможет. Ма и тётушки всегда так со всем, когда охотник ранен. — *Хочет хоть с чем-то помочь.*\n\n//Ну, чистую воду хотя бы делу организую",177926,null],[184182,"2026-09-01T14:49:21",17,"— Да, вода это жизнь, Иллуг. Нужно пить. Кровь сама собой не появится.",177926,null],[184189,"2026-09-01T14:52:19",17,"За маленьким оконцем движется зимняя ночь. \n\nНалгын вдруг указывает тебе на небольшое окошко\n\nСначала кажется, что это просто метель играет с тенями между деревьев. Потом одна белая фигура выходит из темноты.\n\nОлень. Высокий, тонконогий, с ветвистыми рогами, покрытыми инеем. Его тело будто соткано из лунного света и тумана. Сквозь него видны стволы деревьев.\n\nСледом появляется второй. Третий. Между ними идут люди.\nСтарые охотники в мехах и костяных украшениях, женщины в тяжёлых зимних одеждах, подростки с копьями, седые старики, чьи лица будто вырезаны из снега и пепла.\nС ними бегут собаки. Тоже бледные, полупрозрачные, беззвучные.\n\nНикто не говорит. Никто не оглядывается.\n\nОни движутся ровно и спокойно, словно знают дорогу лучше живых. Снег под их ногами не мнётся. Тьма леса расступается перед ними без ветра и без звука.\nИ только когда одна высокая фигура в старой меховой парке проходит мимо окна, на миг кажется, будто пустые белёсые глаза смотрят прямо внутрь.\n\nНо шаг не сбивается. Процессия идёт дальше. Медленно и тихо.\n\nСловно весь лес этой ночью принадлежит не живым.",177926,null],[184204,"2026-09-01T14:57:36",9,"— Они... уходят? — *Спросил Иллуг подавая очищенную воду, о том что увидел в окошке. А потом посмотрел на охотника. Парень плохо знал о таких маршах мертвых, но интуитивно чувствовал, как бы духи не пришли за ком то из них, скорей всего охотником.*",184189,null],[184233,"2026-09-01T15:27:54",17,"Налгын долго смотрит в окно, не приближаясь к нему.\n\n— Не бойся их. Они не за нами пришли. Они вообще ни за кем не приходят. Просто идут своей дорогой.\n\nОн говорит тихо, почти буднично.\nСтарик подбрасывает полено в огонь.\n\n— Но мёртвые плохо понимают разницу между тем, кто уже ушёл, и тем, кто только собирается.\n\nОн кивает в сторону раненого.\n\n— Поэтому дверь не открывай. Их не отпускай. И по именам никого не зови, даже если покажется, что узнал лицо.\n\nНалгын щурится, наблюдая за белыми фигурами между деревьев.\n\n— Старики учили меня когда идёт Зимняя Тропа, живому полагается сидеть у огня и помнить, зачем ему нужно дождаться утра. А еще считать их нельзя.\n\nОн усмехается краем рта.\n\n— Никогда не знаешь, на каком числе сам окажешься среди них.",177926,null],[184238,"2026-09-01T15:47:51",17,"— Зачем тебе нужно дожить до утра, Иллуг? Ради них? \n\nКивает на собак\n\n— Или ради иного?",177926,null],[184254,"2026-09-01T16:05:43",9,"— Я не знаю. — *Иллуг не выдумывал и сказал как есть, он погладил Нанухака (медвежонка) что хоть и лаял громне всех но трусился немного со страху до сих пор.* — У меня лишь они.\n\n— Хочется увидеть края долгого лета, о которых расказывали птицы. — *И найти возможно свою семью, но он этого уже не сказал.*",177926,null],[184271,"2026-09-01T16:12:31",17,"— Лишь они уже немало.\n\nСтарик протягивает ладонь к огню\n\n— А края долгого лета... Хорошая причина. Глупая, далёкая, почти невозможная. Значит, настоящая.\n\n— Доживи сначала до утра, Иллуг. Потом до следующего. А там, может быть, однажды проснёшься и обнаружишь, что дошел.\n\nСтарик больше ничего не спрашивает. Раненый успокоился, жар ослаб. Налгын тоже стал укладываться спать.",177926,null],[184294,"2026-09-01T16:15:54",17,"/Внимание",177926,null],[184304,"2026-09-01T16:21:02",9,"/roll 1d20+2 внимание",177926,null],[184313,"2026-09-01T16:22:50",9,"*Сонный и уставший, глаза сами слипаются уже, ни о каком внимании не может идти и речи.*\n\n//Вот она моя удача, крит уравновесил крит провал, колесо крутится и так всегда",184305,null],[184357,"2026-09-01T16:37:25",17,"/Знаешь тут бог отвёл. Ты не заметил того чего и не должен был)",177926,null],[184444,"2026-09-01T16:57:29",17,"Утро приходит серым. Огонь почти погас. За окном нет ни следа ночной процессии — только чистый снег между деревьями.\nРаненый всё ещё горячий, но дышит ровнее.\n\nНалгын поднимается последним. Поначалу старик ничего не говорит.\n\nВы собираете пожитки\n\n— Нужно торопиться, отвезём его на мою стоянку он оттуда.\n\nОни проходят совсем немного, когда позади слышится хруст снега. Налгын стоит на одном колене. Одна ладонь упирается в землю.\n\n— Не смотри так.\n\nОн пытается подняться и со второй попытки выпрямляется.\n\n— Старые ноги решили напомнить, сколько им лет.\n\nНо улыбка получается слабой.\n\nСтарая дорога спускается по склону дороги, но часть снега сошла вместе с землёй, оставив узкий проход над камнями.\n\nНалгын смотрит вниз. Потом на сани. Потом на Иллуга.\n\n— Ну что, птенец. Теперь старые мои кости, ведёшь ты.",177926,null],[185096,"2026-09-02T01:38:54",9,"//Там та долинка что на картинке в итоге? Я плохо осознаю описание чтобы понять в чем трудность.",184444,null],[185106,"2026-09-02T08:22:39",17,"/ Сейчас пока препяттвия нет. Кроме того, что деда покидают силы, ему нужно помогать идти, а на санях раненый",177926,null],[185107,"2026-09-02T08:22:50",17,"/ А вот препятствие",177926,null],[185109,"2026-09-02T08:25:37",17,"Дорога постепенно сужается между деревьями.\n\nНалгын идёт всё медленнее. Несколько раз Иллуг замечает, как старик незаметно опирается ладонью о стволы, будто просто рассматривает кору.\n\nНа санях охотник снова начинает бредить. От него идёт жар даже через меха.\n\nНаконец лес впереди обрывается. Через глубокий овраг когда-то был перекинут старый мост из толстых брёвен.\n\nБыл.\n\nТеперь половина настила лежит далеко внизу среди чёрных камней. Остались несколько скользких стволов и оборванные верёвки.\n\nНалгын подходит к краю. Смотрит вниз. Потом на тяжёлые сани.\n\n— Обходить очень долго, он не дотянет точно.\n\nСтарик кашляет в кулак. Он присаживается возле уцелевших брёвен и проводит рукой по древесине.\n\n— По одному перейдём. Раненого понесём отдельно. Потом собак. Потом пустые сани протянем верёвкой.\n\nНалгын начинает подниматься и на мгновение замирает, опираясь обеими руками о колено.\n\nОн слабо усмехается.\n\n— Ух и задачка для молодого шамана. Не дрейфь, Иллуг, справимся.",177926,null],[185130,"2026-09-02T09:23:33",9,"— Держите Аата Налгын. — *Илуг отдаёт ему своё копьё, где-то зацепиться, где-то закрепиться.* — Путь оно вас не отпускает, пока вы его держите.\n\n//С длинной палкой легче равновесие держать и все такое, пусть дедуле будет, перейдет и мы следом как нибудь",185109,null],[185131,"2026-09-02T09:24:13",17,"— Пойду первым, да, с этим будет наверное попроще",177926,null],[185132,"2026-09-02T09:24:19",17,"/r +2 Акробатика Налгын",177926,null],[185135,"2026-09-02T09:24:36",17,"/Преимущество из-за палки",177926,null],[185136,"2026-09-02T09:29:11",17,"Осторожно Налгын ступает от края моста к бревнам прощупывая их ногой\n\nОн держит копьё перед собой чтобы упростить себе путь, центр тяжести лучше контролируется.\n\nМелкими шагами он идёт по бревну на другую сторону\n\nВдруг он поскальзывается на середине бревна, но благодаря копью удерживает равновесие.\n\nОн перешел\n\n— Так. Теперь, давай раненого, я принимаю тут. Верёвка есть?",177926,null],[185137,"2026-09-02T09:31:33",9,"//Две по 50, но вторая дома, на легке же, ничо лишнего, так что одна.\n\n— Да, немного. — *Показывает верёвку из поклажи своей.* — Что делать Аата Налгын.",177926,null],[185138,"2026-09-02T09:33:32",17,"— Привяжи край к мосту, покрепче, Иллуг. Обвяжи себя за пояс и раненого тоже. Тащить его тебе на закорках придётся. \n\nНалгын снял с шеи костяные амулеты и начал растирать их в руках шепча что то в них.",177926,null],[185139,"2026-09-02T09:33:45",17,"/r +4 Религия Налгын",177926,null],[185141,"2026-09-02T09:33:48",17,"— Не бойся! Духи помогут!",177926,null],[185142,"2026-09-02T09:34:30",17,"/Проверка Акробатики с помехой СЛ12",177926,null],[185143,"2026-09-02T09:35:15",9,"//Ну ща",177926,null],[185144,"2026-09-02T09:35:41",17,"Внизу бушует горный ручей, течение такое быстрое что проталина не затягивается льдом",177926,null],[185145,"2026-09-02T09:35:56",9,"/roll 1d20+1 акробатика ни к чёрту как и все в прочем",177926,null],[185147,"2026-09-02T09:37:21",9,"*Иллуг охотника так чтобы тот то ли висел то ли лежал у него на спине и согнувшись чтобы не упасть и держать хотя бы немного равновесие с такой поклажей пытается пройти по сдоманному мосту.*",177926,null],[185148,"2026-09-02T09:39:56",17,"Брёвна хорошо обтёсаны, гладкие и покрыты тонкой ледяной коркой, даже без раненого охотника на закорках пройти по ним очень сложно, ты подскальзывается у самого конца и заваливаешься с охотником на бок\n\n— ИЛЛУГ, ДЕРЖИ ДРЕВКО!\n\nНаглын бросается к краю, в падении ложится, одной рукой он протягивает тебе древко копья, рам держится у пики, а второй достал кривой кинжал и вонзил его в землю, чтобы не соскальзнуть вместе с вами",177926,null],[185149,"2026-09-02T09:39:58",17,"/Ловкость рук",177926,null],[185151,"2026-09-02T09:41:34",9,"/roll 1d20+1 та же история",177926,null],[185159,"2026-09-02T09:44:19",17,"Древко рядом но ты не успеваешь схватиться за него\n\nСейчас свободное падение разгонит вас до немыслемой скорости, падение и смерть\n\nНалгын видя, что не получилось, отбрасывает копьё рядом и хватается за костяной оберег сжимая его в ладони, острые костяшки пускают ему кровь и амулет бледно светится\n\nРезкий порыв ветра толкает и тебя и раненого в спину внизу. Этот порыв на подъем выбрасывает вас на сторону к Налгыну",177926,null],[185160,"2026-09-02T09:44:49",17,"Старик хрипит, но улыбается\n\nСобаки на той стороне разрушенного моста нервничают и лают",177926,null],[185167,"2026-09-02T09:52:36",9,"*Иллуг когда упал на мост немного ушибся, но ничего, колено поболит и пройдёт, зато жив.*\n\n— Спасибо, спасибо Аата. Вы гуляете с ветром. — *Садится и пытается прийти в себя, падение вызвало прилив адрешалина и шок, даже если он падал раньше, но к этому не привыкнуть, может позволить сеье минуту, или две. Он не спрашивал о ранах, о костяном амулете, каждый говорит о своих тайнах, только если захочет.*",177926,null],[185173,"2026-09-02T09:56:06",17,"— Совсем я старый стал, отдышаться надо, ты пока подумай как собак перевести. А пустые сани, мы уж перетащим. И веревка на тебе нам поможет\n\nОн указывает на веревку которой вы обвязаны, теперь ее можно использовать",177926,null],[185174,"2026-09-02T09:56:19",17,"/Сам подумай пока как использовать, если что спрашивай мудрого старика",177926,null],[185179,"2026-09-02T09:57:44",9,"//Дед мне тесты прилумывает, я бля ебану костяное крюк копте длинное как будет из чего, оно столько проблем решает, лан, придумаю чёт",177926,null],[185182,"2026-09-02T10:15:45",9,"*Иллуг думалс дамал и ничего лучше особо не придумал.*\n\n— Надо обратно, сани положить на брёвна, поклажу и собак легче перекинуть перетащить по ним.\n\n//Ну, если части моста нет, то мы её сделаем",177926,null],[185183,"2026-09-02T10:16:14",9,"//Они типа таких наверное, шире ток и длиннее",177926,null],[185185,"2026-09-02T10:17:32",17,"— Да, хорошо, но чтобы тебе не свалиться, молодой Иллуг. Натяни веревку до вооон того ствола, и так ты сможешь держаться за нее сам руками",177926,null],[185188,"2026-09-02T10:22:38",9,"*Кивает, делает как советует деда Налгын. Застраховавшись, он перешёл на ту сторону, положил пустые сани. Сначала перекидал все вещи по одной на ту сторону, поклажи было немного. После по одному собак, особенно осторожно, хуже всего было с медвежонком, тот не смотря на то что самый крупный боялся всего, высоты и пруда тоже.*",185185,null],[185190,"2026-09-02T10:27:16",17,"Налгын помог перетянуть на санях поклажу\n\nНо вот собак тебе успокаивать самому",177926,null],[185191,"2026-09-02T10:27:19",17,"/Уход за животными",177926,null],[185192,"2026-09-02T10:31:55",9,"//Думаю там проблема основном с Нанухаком, щас посмотрим",177926,null],[185193,"2026-09-02T10:32:49",9,"*Иллуг понимает что с медвежёнком бцдет хуже всего. Пытается всё же прикормить его той сахарной косточкой что он не схотел прошлый раз.*",177926,null],[185194,"2026-09-02T10:33:06",9,"/roll 1d20+1 уход, надеюсь не с животными вместе",177926,null],[185197,"2026-09-02T11:02:00",17,"Нанунах никак не хочет идти, остальные уже перебрались",177926,null],[185198,"2026-09-02T11:02:23",17,"— Ветер усиливается Иллуг! Попробуй еще что-нибудь!\n\nПронизывающий холодный ветер крепчает",177926,null],[185204,"2026-09-02T11:09:12",9,"*Иллуг садиться перед медвежёнком и обнимает его, говорит.*\n\n— Надо идти, надо идти Нанухак. Не бойся, послушай, я рядом, я поддержу. — *Зарывшись лицом в густую шерсть, он просит, он говорит, он заклинает, как помнит.*\n\n//Ну, тут уже ритуал разговор а с животными, пробую его словами успокоить чтобы понял",177926,null],[185233,"2026-09-02T11:28:50",17,"/У тебя есть ритуал разговора с животными?",177926,null],[185242,"2026-09-02T11:31:28",9,"// Разговор с животными и очищение воды и питья, я эти два взял ритуальным заклинателем, выбирал от мудрости чертой ритуалы друида. Но нарративно Иллуг пока не полностью освоил ритуал или не понимает, он понимает в ответ только то что говорят птицы, не животные",177926,null],[185251,"2026-09-02T11:37:30",17,"/Кинь просто уход за животными  с преимуществом за объятия",177926,null],[185252,"2026-09-02T11:37:44",17,"/Ритуал 10 минут так сидеть, а ветер усиливается",177926,null],[185255,"2026-09-02T11:41:41",9,"/roll +d20+1 уход",177926,null],[185816,"2026-09-02T17:49:42",17,"Ваша связь крепнет в объятьях Нанухак успокаивается и вы вместе перебираетесь на ту сторону он на санях, а ты держась за верёвку\n\nСани тоже удаётся вытянуть",177926,null],[185820,"2026-09-02T17:50:26",17,"На другой стороне оврага они собираются долго. Собаки тяжело дышат.\nОхотник мечется под мехами и что-то бессвязно шепчет.\n\nНалгын садится прямо в снег. На этот раз не шутит. Несколько мгновений просто смотрит на свои руки.\n\n— Странно.\n\nОн сжимает пальцы.\n\n— Будто они чужие.\n\nПотом всё же поднимается, опираясь на плечо Иллуга.\n\n— Недалеко осталось.\n\nСтарик смотрит между деревьев.\n\n— За той грядой увидим дым.",177926,null],[185821,"2026-09-02T17:50:51",17,"Они идут дальше. Через некоторое время Налгын вдруг спрашивает\n\n— Как его зовут?\n\nОн кивает на раненого.\n\nИ почти сразу хмурится.\n\n— Нет... погоди. Я ведь знаю его.\n\nСтарик долго смотрит на лицо охотника.\n\n— Знал.\n\nНалгын трёт висок.\n\n— Старость...",177926,null],[185853,"2026-09-02T18:15:19",9,"— Не переживайте Аата Налгын. Мы уже близко, ваши слова, еще немного. — *Иллуг улыбается подбадривая старика, а сам думает хоть бы они успели, пусть так, делушку Налгына он не собирался никак высмеиыать или упрекать за его старость.*",177926,null],[185855,"2026-09-02T18:18:57",17,"/ Если есть заявочки на броски навыков говори",177926,null],[185856,"2026-09-02T18:19:32",17,"Виднеется стойбище Налгына",177926,null],[185860,"2026-09-02T18:20:49",9,"//Я не знаю что делать если честно, вайбово но дорога и дорога, максимум вон бревна и преграды обойти или убрать",177926,null],[185861,"2026-09-02T18:21:04",17,"/ Дорога это не главное)",185860,null],[185862,"2026-09-02T18:21:15",17,"/ Хорошо, если нет заявок, просто идём дальше, это нормально",177926,null],[185863,"2026-09-02T18:21:27",17,"Дым они видят раньше домов. Тонкие серые столбы поднимаются между деревьев.\nСобаки чувствуют стойбище почти сразу. Апутсиак поднимает голову, Анука тянет сильнее, и даже уставшие лапы начинают идти быстрее.\nНалгын смотрит вперёд, а потом улыбается.\n\n— Домой пришли, птенец.\n\nМежду деревьев появляются крыши. Кто-то замечает упряжку.\nРаздаётся крик. Люди выбегают навстречу. Несколько мужчин сразу узнают лежащего на санях охотника.\n\n— Живой!\n\n— Знахаря зовите!\n\n— Осторожнее, осторожнее!\n\nЛюди окружают сани.\n\nКто-то принимает поводья у Иллуга. Кто-то хватает раненого под плечи.\n\nМимо Налгына проходят двое. Не поздоровавшись. Старик смотрит им вслед. Хмурится. \nЕщё одна женщина пробегает почти вплотную к нему. Даже не поднимает глаз.\n\nНалгын медленно переводит взгляд на Иллуга.\n\n— Странно...\n\nОдин из жителей наконец спрашивает тебя\n\n— Кто ты? Откуда его привёз?",177926,null],[185869,"2026-09-02T18:25:59",9,"— Я Иллуг (друг). Встретил Аату Налгына, нам было по пути. Мы шли и увидели следы, кровь, медведь ел оленя, раненый охотник. Я попросил большого Нанухака отдать охотника, он согласился и не тронул нас, Аата Налгын сказал тут его дом, сюда и спешил. — *Иллуг коротко как мог пересказал историю, вёл упряжку куда говорили, уставший но рад что успел.*",185863,null],[185871,"2026-09-02T18:26:38",17,"Шум вокруг саней постепенно стихает.\n\nОдна старая женщина медленно поворачивает голову.\n\n— Налгын?\n\n— Что ты сказал?",185869,null],[185872,"2026-09-02T18:29:54",9,"*Тоже смотрит на старого шамана, не понимая что может что-то не так?*",185871,null],[185873,"2026-09-02T18:30:22",17,"Женщина бледнеет.\n\n— Мальчик...\n\nОна подходит ближе.\n\n— Налгын умер.\n\nНесколько мгновений слышно только тяжёлое дыхание собак.\n\n— Семь дней назад. После пурги. Охотники нашли его между Чёрными Камнями.",177926,null],[185874,"2026-09-02T18:30:53",17,"Налгын не двигается.\n\nУлыбка исчезает с его лица.\n\n— Между камнями...\n\nОн смотрит на собственные руки.\n\n— Я лёг там.\n\nТишина.\n\n— Ветер был сильный.\n\nСтарик медленно садится на ближайшее бревно.\n\n— Думал, глаза ненадолго прикрою.\n\nОн вдруг тихо смеётся. Без веселья.\n\n— Вот ведь старый дурак.",177926,null],[185884,"2026-09-02T18:40:13",9,"*Иллуг смотрит на остальных.*\n\n— Я... деда мне очень помог. Он тут. — *Иллуг садится рядом со стариком, видят его остальные или нет, слышат или нет он говорит уже с ним.* — Спасибо Аата Налгын, вы чуяли чудую беду и не ушли.\n\n*Он сидит так некоторое время и продолжает.*\n\n— Аана (бабуля) я ее полохо помню. Она хотела чтобы о ней забыли, чтобы её не держали, когда она умрёт в третий раз, как в вашей сказке, она сможет уйти. — *Он улыбнулся.* — Почти не помню Аану (бабушку), больше никто не помнит. Она хотела уйти, она знала. Может и вам Аата Налгын нудно идти.\n\n//Что удивительно у инуитов я прослеживал какой-то аналог сансары и перерождения, когда от человека ничего не остается в мире он сможет пойти дальше. На счет перерождения ли не уверен, всё же их мифы образны чем точные. Ну или иногда мертвецы становились злыми духами, дед похоже станет если не подумает уходить, чую пятой точкой",177926,null],[186639,"2026-09-02T22:03:24",17,"Налгын поднимает глаза на Иллуга.\n\nТеперь в них нет растерянности. Только усталость.\n\n— Значит, домой я всё-таки сам не дошёл, Иллуг. Прав ты, прав. \n\n— Ты меня не привёл.",177926,null],[186650,"2026-09-02T22:07:03",17,"— Иллуг, да? Мальчик ты Нуртана спас. Охотник наш молодой. Благодарны тебе. А Налгына нет уже. Прости. Могила его вон за околицей. Сходи туда сынок, если простится хочешь и знал его.",177926,null],[187010,"2026-09-02T23:32:30",9,"— Аата Налгын, он ветер, шёл домой но не дошёл. — *Иллуг кивнул и взял старого шамана за руку.* — Мы почти дошли.\n\n*Ведёт его к своей могиле, дух остался там, не поверил в свою смерть, не дошёл.*",177926,null],[187022,"2026-09-02T23:34:39",17,"— Хорошо уложили. \n\nНалгын долго стоит у собственной могилы.\n\nПотом снимает с плеч мех, аккуратно складывает рядом и медленно ложится поверх холодной земли, будто просто устраивается на ночлег после долгой дороги.\n\n— Вот теперь дошли.\n\nСтарик смотрит на Иллуга.\n\n— Хорошо проводил, птенец.\n\nВетер проходит между камней.\nКонтуры Налгына становятся прозрачнее.\nИ вдруг всё вокруг исчезает.",187010,null],[187025,"2026-09-02T23:35:40",9,"//Всё или дед 🤔",177926,null],[187049,"2026-09-02T23:38:55",17,"Вспышка в памяти.\n\nЛёд ломается под Анукой.\n\nНо ремень вокруг собаки затягивают руки Иллуга. Налгына нет рядом. Вытянул сам.\n\nВспышка.\n\nМедведь ревёт над окровавленным снегом.\nИ Иллуг сам поднимает собак и запугивает зверя.\n\nВспышка.\n\nСтарик говорит у костра.\nНо слова звучат внутри собственной головы Иллуга.\nЧужие воспоминания смешиваются с его собственными: старые тропы, имена духов, запах жертвенного дыма, голоса давно умерших учителей.\n\nИллуг падает с раненым за плечами с бревна. В реку. Не хочет умирать. Не хочет терять надежду. Северный ветер отзывается ему и толкает из пропасти. \nНе Налгын. Сам Иллуг призвал его.\n\nИ приходит понимание. Налгын не спасал его.\nНалгын был заблудшим духом.\n\nА всю дорогу молодой шаман сам вёл мёртвого домой. Сам решал беды. Сам довел его чтобы тот обрёл покой. \n\nВпитал мудрость духа и его занния. Не разгневал иных.",177926,null],[187051,"2026-09-02T23:39:12",17,"/ Налгын - Тайлер Дерден",177926,null],[187065,"2026-09-02T23:41:26",17,"Мир возвращается.\nИллуг стоит у могилы.\n\nРядом один за другим подходят собаки.\nОдна прижимается к ноге. Вторая садится рядом. Третья опускает тяжёлую голову ему на бедро. Четвертый устраивается впереди, глядя на могилу.\n\nНа мгновение среди собак снова виден Налгын.\n\nГорный ветер проходит через стойбище.\n\nОн кружит вокруг рук Иллуга, касается нарисованных птиц и послушно ложится ему на ладонь.\n\nНалгын обрёл покой.\n\nА Иллуг впервые понял - птицы были не единственными, кого он способен слышать.",177926,null],[187066,"2026-09-02T23:41:34",17,"/ Уход за животными думаю",177926,null],[187068,"2026-09-02T23:42:09",9,"/roll 1d20+1 уход за ними",177926,null],[187071,"2026-09-02T23:42:17",17,"/))",177926,null],[187072,"2026-09-02T23:42:17",9,"//Конечно)",177926,null],[187077,"2026-09-02T23:44:37",17,"На одно мгновение ты видишь среди собак силуэт Налгына. Он стоит ровно и улыбается. \n\nДух горного ветра вселяется в одну из собак, в Ануку. \n\nОна поворачивает на тебя морду и ты видишь как зрачки изменились, дух внутри Ануки. Он решил остаться с тобой. \n\nПомогать тебе.\n\nНо какой ценой. \n\nАнука теперь спит. Пока дух занял ее тело. \n\nЧто ты будешь делать?",177926,null],[187088,"2026-09-02T23:49:01",9,"//Я ничё не понимаю опять, ну типа все ясно, но не понятно что с этим делать 😂👍",177926,null],[187092,"2026-09-02T23:50:02",9,"//Ну, Анука был ветром теперь он ветер",177926,null],[187096,"2026-09-02T23:50:30",17,"/ Ну давай напишу в лоб.\n\nКак то пытаться духа изгнать и вернуть настоящую собаку или ходить с собакой которой контроль дух. Анука тогда считай мертва",177926,null],[187108,"2026-09-02T23:54:36",9,"*Уннук погладил Аннуку и молвил.*\n\n— Как бы вам не хотелось остаться аата (деда) Налгын, вам нужно идти. Все идут, моя аана (бабушка) уйдёт, моя семья уйдёт, все они когда-то уйдут. — *Он улыбнулся.* — А за ними уйду и я. Мёртвым легче чем живым, наша участь учится и деть ошибки, жить, как ты меня учил аата.",177926,null],[187109,"2026-09-02T23:58:45",17,"/ Убеждение",177926,null],[187110,"2026-09-02T23:59:24",9,"/roll 1d20+1 дед ну тебе пора",177926,null],[187113,"2026-09-03T00:02:57",17,"Собака отходит от тебя подальше и рычит \n\nВокруг нее собирается вихрь их снежинок поднятых порывом ветра",177926,null],[187114,"2026-09-03T00:03:04",17,"/ Инициатива",177926,null],[187133,"2026-09-03T00:17:38",17,"Ты понимаешь - убить духа можно только вместе с Анукой. Но, возможно, это не единственный способ победить.\n\nВопросы на поверхности, сразу возникают у тебя в голове \nПочему дух сделал это?\nСлышит ли тебя Анука.\n\nПод твой ладонью пролетает холодный горный ветерок. Сперва в одну сторону, зато обратно.",177926,null],[187140,"2026-09-03T00:35:14",9,"//Я подумаю",177926,null],[187141,"2026-09-03T00:35:23",9,"/roll 1d20+1 иня",177926,null],[187204,"2026-09-03T11:37:01",9,"//Мне катастрофически сложно чет придумать, чёт вообще идеи не идут. Квест крутой но хз что делать, прости что не могу сразу ответить и решить что делать.",177926,null],[187289,"2026-09-03T13:32:10",17,"/r +2 Дух северного ветра",177926,null],[187294,"2026-09-03T13:37:38",17,"У твоей Ануки загораются глаза цвета северного сияния\n\nОт собаки в тебя начинают лететь снежинки, сначала мало. Ветер холодный, он крепчает, давит сильнее и уже буран в конусе от духа внутри Ануки давит на тебя.\n\n/Атлетика",177926,null],[187297,"2026-09-03T13:38:11",17,"Остальные собаки тоже страдают, взъерошились, сопротивляются",177926,null],[187300,"2026-09-03T13:38:34",17,"/r 3d20+1",177926,null],[187302,"2026-09-03T13:39:10",17,"Только Нанухак устоял и сделал шаг вперед сквозь буран",177926,null],[187303,"2026-09-03T13:39:32",17,"/Твой ход.",177926,null],[187304,"2026-09-03T13:42:27",9,"/roll 1d20+1 ну атлетика вродь",177926,null],[187306,"2026-09-03T13:45:58",9,"*Иллуг идёт вперёд, преодолевая буран, поднимает руку и... ложит ее на голову Ануки.*\n\n— Анука, пора домой. Анука, проснись, пора домой.\n\n//14 как и у Нанухака, так что думаю справился тоже",177926,null],[187307,"2026-09-03T13:47:09",17,"Ты устоял \n\n/Твоя скорость 5 футов в потоке этого ветра. Анука на расстоянии 10.",177926,null],[187308,"2026-09-03T13:47:42",9,"//Ну, похоже надо еще ход, но я все равно говорю",177926,null],[187309,"2026-09-03T13:47:52",17,"/ Уход за животными кинь",187306,null],[187310,"2026-09-03T13:48:02",9,"/roll 1d20+1",177926,null],[187312,"2026-09-03T13:48:49",17,"Дух северного ветра не хочет уходить, не понимает почему ты не берёшь его с собой, почему прогоняешь\n\n/ Сложность атлетики повысилась с 12 до 13",177926,null],[187313,"2026-09-03T13:49:21",17,"В потоке появляются осколки льда",177926,null],[187314,"2026-09-03T13:49:30",17,"/r 3d20+2",177926,null],[187316,"2026-09-03T13:49:52",9,"/roll 1d20+1 атлетика",177926,null],[187318,"2026-09-03T13:50:00",17,"/Кд больше 12?",177926,null],[187319,"2026-09-03T13:50:10",9,"//Щас дохожу наконец?)",177926,null],[187320,"2026-09-03T13:50:54",9,"//11 кд вроде у меня, у собак 13",187318,null],[187321,"2026-09-03T13:51:37",17,"/r +1 Атлетика Нанухка",177926,null],[187323,"2026-09-03T13:51:58",17,"Медвежоног не выдержал и проскальзил дальше\n\nно ты идёшь",177926,null],[187324,"2026-09-03T13:52:02",17,"/ 3 урона от сосулек",177926,null],[187325,"2026-09-03T13:52:06",17,"/ Твой ход",177926,null],[187327,"2026-09-03T13:52:18",17,"/ Дошел до Ануки",177926,null],[187330,"2026-09-03T13:54:15",9,"*За ветром было не слышно, но на этот раз он дошёл и обнял Аннуку, уткнувшись лицом в его шею. Слёзы проступили, может от холодного ветра.*\n\n— Возвращайся домой Анука, не уходи. Пора домой Анука.",187306,null],[187334,"2026-09-03T13:54:49",17,"/ Уход за животными с преимуществом",177926,null],[187336,"2026-09-03T13:55:14",9,"/roll +d20+1 уход",177926,null],[187821,"2026-09-03T19:16:08",17,"Раненый ледяным ветром ты обхватываешь шею Ануки и крепко сжимаешь\n\nХолод начинает медленно отходить, идти на спад\n\nА в щеку ты чувствуешь как Анука лижет тебя.\n\nКак раньше.\n\nДух ледяного ветра ушел. Рассеялся.\n\nОстальные собаки тоже подбежали и окружили вас. Разбавляя хмурый день звонким лаем.",177926,null],[187835,"2026-09-03T19:19:05",17,"/ Квест завершён. \n\nТы получил 100 опыта за избегание медведя. (Половина от обычного)\n\n200 опыта за отыгрыш.\n\nНу и 200 за завершение квеста.",177926,null],[187917,"2026-09-03T19:39:36",9,"*Иллуг тихо рассмеялся. Аата Налгын стал его семьёй за это короткое время и учителем, но он дух и ему пора идти. Мёртвых нудно отпускать, живых он так просто не отпустит.*\n\n— Анука, хороший пёс. — *Он ещё немного пообнимался, проводил старого шамана, отлав ему почести и пошёл, возможно вскоре он отправится в теплые края о которых говорили птицы.*",177926,null],[188978,"2026-09-04T10:51:55",17,"/Кстате я думаю за каждый брошеный Уход за животными на квесте можешь смело записать себе 3 очка в прогресс \n\nТут их было 9 бросков",177926,null],[188979,"2026-09-04T10:55:57",9,"//Тоесть можно утроить прогресс каждого дня? Оке",177926,null],[188984,"2026-09-04T11:03:13",17,"/ Ну как хочешь, я просто думал добавить +27 очков к прокачке",188979,null],[188985,"2026-09-04T11:03:39",9,"//По механу я просто могу обучаться втрое быстрее)",177926,null]]);
